<script lang="ts">
 let {data}=$props();
 let e=$derived(data.entity as Record<string,any>);
 let connections=$derived(data.connections as Record<string,any>[]);
 let gets=$derived(data.gets as Record<string,any>);
 let rfx=$derived(gets?.rfx as Record<string,any>|null);
 let supplier=$derived(gets?.supplier as Record<string,any>|null);
 let regions=$derived((gets?.regions??[]) as Record<string,any>[]);
 let categories=$derived((gets?.categories??[]) as Record<string,any>[]);
 let suppliers=$derived((gets?.suppliers??[]) as Record<string,any>[]);
 let relatedRfx=$derived((gets?.relatedRfx??[]) as Record<string,any>[]);
 let metadata=$derived(parseMetadata(e.metadata_json));
 let getsKind=$derived(metadata?.gets?.kind as string|undefined);
 let isCharityOfficerRecord=$derived(String(e.slug??'').startsWith('charities-officer-'));
 let isGetsAgencyRecord=$derived(getsKind==='agency');
 const relationshipLabels:Record<string,{out:string;in:string}>={OFFICER_OF:{out:'Officer of',in:'Officer'},ISSUED:{out:'Issued by',in:'Issued'},AWARDED_TO:{out:'Awarded to',in:'Awarded supplier for'}};
 function parseMetadata(raw:unknown){try{return raw?JSON.parse(String(raw)):{};}catch{return {};}}
 function relationshipLabel(predicate:string,direction:string){const known=relationshipLabels[predicate];if(known)return direction==='out'?known.out:known.in;const fallback=String(predicate).replaceAll('_',' ').toLowerCase().replace(/^./,(c)=>c.toUpperCase());return direction==='out'?fallback:`Connected by ${fallback.toLowerCase()}`;}
 function recordType(){if(rfx)return rfx.award_type==='Not Awarded'?'Procurement record':'Award notice';if(supplier)return 'GETS supplier evidence record';if(isGetsAgencyRecord)return 'GETS agency record';return isCharityOfficerRecord?'Charity officer record':String(e.entity_type).replace('_',' ');}
 function valueOrMissing(value:unknown){return value===null||value===undefined||value===''?'Not supplied':String(value);}
</script>
<svelte:head><title>{e.canonical_name} · NZ Records</title></svelte:head>
<header><div><a class="brand" href="/">NZ Records</a><nav><a href="/explore">Search</a><a href="/directory?kind=charities&letter=A">Charities</a><a href="/directory?kind=officers&letter=A">Officer records</a></nav></div></header>
<main><p class="breadcrumb"><a href="/explore">Search records</a> / Record</p><section class="identity"><p class="type">{recordType()}</p><h1>{e.canonical_name}</h1><p class="status">{e.status??'Status not supplied'}</p>{#if e.nzbn||e.company_number||rfx||supplier}<dl class="ids">{#if e.nzbn}<div><dt>NZBN</dt><dd>{e.nzbn}</dd></div>{/if}{#if e.company_number}<div><dt>Company number</dt><dd>{e.company_number}</dd></div>{/if}{#if rfx}<div><dt>RFx ID</dt><dd>{rfx.rfx_id}</dd></div>{/if}{#if supplier}<div><dt>GETS supplier row</dt><dd>{supplier.supplier_record_key}</dd></div>{/if}</dl>{/if}
{#if isCharityOfficerRecord}<aside class="note"><strong>About this record</strong><span>This is an officer record for one charity. The same person may have other records on this site, but we don't combine them unless we can be sure they're the same person.</span></aside>{/if}
{#if supplier}<aside class="note"><strong>About this supplier record</strong><span>This supplier name appears in a GETS procurement record. NZ Records has not yet linked this supplier evidence record to a verified legal entity.</span></aside>{/if}
{#if isGetsAgencyRecord}<aside class="note"><strong>About this agency record</strong><span>This agency identity is the exact posting-agency name from GETS. NZ Records has not merged it with agencies from other datasets.</span></aside>{/if}</section>
{#if rfx}<section class="gets"><div class="heading"><h2>GETS procurement details</h2><span>{rfx.award_type==='Not Awarded'?'Procurement record':'Award notice'}</span></div><article><dl class="facts"><dt>RFx ID</dt><dd>{rfx.rfx_id}</dd><dt>Title</dt><dd>{rfx.title}</dd><dt>Status / award type</dt><dd>{valueOrMissing(rfx.award_type)}</dd><dt>Posting agency</dt><dd><a href={`/record/${rfx.agency_entity_id}`}>{rfx.posting_agency}</a></dd><dt>Reported award value</dt><dd>{valueOrMissing(rfx.awarded_amount_raw)}</dd><dt>Open date</dt><dd>{valueOrMissing(rfx.open_date)}</dd><dt>Close date</dt><dd>{valueOrMissing(rfx.close_date)}</dd><dt>Awarded date</dt><dd>{valueOrMissing(rfx.awarded_date)}</dd></dl>
{#if regions.length}<div class="chips"><strong>Regions</strong>{#each regions as region}<span>{region.region}</span>{/each}</div>{/if}
{#if categories.length}<div class="chips"><strong>UNSPSC categories</strong>{#each categories as category}<span>{category.unspsc_code} — {category.unspsc_description}</span>{/each}</div>{/if}
<div class="supplier-links"><strong>{suppliers.length?'Supplier records':'Supplier records: none'}</strong>{#each suppliers as s}<a href={`/record/${s.entity_id}`}>{s.business_name}<small>{s.nzbn_quality}</small></a>{/each}</div>
{#if rfx.award_type==='Not Awarded'}<aside class="note"><strong>Not awarded</strong><span>This GETS record is marked Not Awarded, so NZ Records shows no awarded-to supplier relationship for it.</span></aside>{/if}</article></section>{/if}
{#if supplier}<section class="gets"><div class="heading"><h2>GETS supplier evidence</h2><span>Not verified legal identity</span></div><article><dl class="facts"><dt>Supplier name</dt><dd>{supplier.business_name}</dd><dt>Related RFx</dt><dd>{#each relatedRfx as record}<a href={`/record/${record.entity_id}`}>{record.rfx_id} — {record.title}</a>{/each}</dd><dt>Raw NZBN value</dt><dd>{valueOrMissing(supplier.raw_supplier_nzbn)}</dd><dt>NZBN quality</dt><dd>{valueOrMissing(supplier.nzbn_quality)}</dd><dt>Identity status</dt><dd>Not linked to a verified legal entity</dd></dl></article></section>{/if}
<section class="connections"><div class="heading"><h2>{isCharityOfficerRecord?'Connections for this record':'Connections'}</h2><span>{connections.length} {connections.length===1?'connection':'connections'}</span></div>
{#each connections as c}<article><div class="relationship"><span>{relationshipLabel(c.predicate,c.direction)}</span><div><a href={`/record/${c.connected_id}`}>{c.connected_name}</a><small>{String(c.connected_type).replace('_',' ')}{c.connected_status?` · ${c.connected_status}`:''}</small></div></div><details><summary>View source</summary><div class="evidence"><p><strong>Source</strong><a href={c.source_url} target="_blank" rel="noreferrer">{c.publisher} — {c.dataset} ↗</a></p><dl>{#if c.record_id}<dt>Record</dt><dd>{c.record_id}</dd>{/if}{#if c.published_at}<dt>Published</dt><dd>{c.published_at}</dd>{/if}<dt>Retrieved</dt><dd>{c.retrieved_at}</dd>{#if c.licence}<dt>Licence</dt><dd>{c.licence}</dd>{/if}</dl></div></details></article>{/each}
{#if connections.length===0}<div class="empty">No connections are currently loaded for this record.</div>{/if}</section>
<aside class="disclaimer"><strong>What does a connection mean?</strong><span>NZ Records shows relationships found in public records. A connection does not by itself imply wrongdoing, influence or endorsement. Check the source to see the evidence behind it.</span></aside></main>
<style>:global(*){box-sizing:border-box}:global(body){margin:0;background:#f7f7f4;color:#202624;font-family:Arial,Helvetica,sans-serif}:global(a){color:#135f50}header{background:#fff;border-top:5px solid #176b5a;border-bottom:1px solid #d9ddd9}header>div{max-width:960px;margin:auto;padding:19px 28px;display:flex;justify-content:space-between;align-items:center}.brand{font-size:22px;font-weight:700;color:#202624;text-decoration:none}header nav{display:flex;gap:24px}header nav a{font-size:14px;font-weight:600}main{max-width:960px;margin:auto;padding:38px 28px 90px}.breadcrumb{font-size:13px;color:#68726e;margin:0 0 32px}.identity{padding-bottom:35px;border-bottom:1px solid #cbd1cc}.type{font-size:14px;font-weight:700;color:#176b5a;text-transform:capitalize;margin:0}.identity h1{font-family:Georgia,'Times New Roman',serif;font-size:clamp(40px,6vw,58px);line-height:1.08;letter-spacing:-.025em;margin:9px 0}.status{font-size:17px;color:#58625e}.ids{display:flex;gap:45px;margin:28px 0 0;flex-wrap:wrap}.ids div{display:flex;flex-direction:column;gap:4px}.ids dt{font-size:12px;font-weight:700;color:#59635f}.ids dd{margin:0;font-size:14px}.note{max-width:750px;background:#eef4f1;border-left:5px solid #176b5a;padding:17px 20px;margin-top:28px;display:flex;flex-direction:column;gap:6px;line-height:1.5}.note span{color:#46504c}.connections,.gets{padding-top:36px}.heading{display:flex;justify-content:space-between;align-items:baseline;border-bottom:2px solid #6e7873;padding-bottom:12px}.heading h2{font-family:Georgia,'Times New Roman',serif;font-size:30px;margin:0}.heading span{font-size:13px;color:#68726e}article{background:#fff;border-bottom:1px solid #d5dad6;padding:20px 16px}.relationship{display:grid;grid-template-columns:150px 1fr;gap:20px}.relationship>span{font-size:13px;font-weight:700;color:#4e5955}.relationship div{display:flex;flex-direction:column;gap:5px}.relationship a{font-size:17px;font-weight:700}.relationship small{font-size:13px;color:#69736f}details{margin:15px 0 0 170px}summary{color:#135f50;text-decoration:underline;cursor:pointer;font-size:13px}.evidence{margin-top:13px;background:#f2f4f2;border:1px solid #d1d6d2;padding:15px}.evidence p{margin:0;display:flex;flex-direction:column;gap:5px;font-size:13px}.evidence dl,.facts{display:grid;grid-template-columns:120px 1fr;gap:7px 12px;font-size:12px;margin:15px 0 0}.evidence dt,.facts dt{font-weight:700;color:#5b6561}.evidence dd,.facts dd{margin:0}.facts{grid-template-columns:160px 1fr;font-size:14px;margin:0}.facts dd{line-height:1.45}.facts dd a{display:block;font-weight:700}.chips,.supplier-links{display:flex;gap:8px;flex-wrap:wrap;margin-top:18px}.chips strong,.supplier-links strong{width:100%;font-size:12px;color:#4e5955}.chips span{background:#eef4f1;border:1px solid #cbd1cc;border-radius:999px;padding:7px 10px;font-size:12px;color:#46504c}.supplier-links{flex-direction:column}.supplier-links a{display:flex;justify-content:space-between;gap:18px;border-top:1px solid #d5dad6;padding-top:10px;font-weight:700}.supplier-links small{font-weight:600;color:#69736f}.empty{padding:30px 16px;background:#fff;color:#69736f}.disclaimer{border-top:1px solid #cbd1cc;margin-top:45px;padding-top:22px;display:flex;flex-direction:column;gap:7px;color:#59635f;line-height:1.55;font-size:13px}.disclaimer strong{color:#202624}@media(max-width:650px){header>div{align-items:flex-start;flex-direction:column;gap:15px}header nav{flex-wrap:wrap;gap:12px 18px}.ids{flex-direction:column;gap:14px}.relationship,.facts{grid-template-columns:1fr;gap:7px}details{margin-left:0}.heading{align-items:flex-start;flex-direction:column;gap:5px}}</style>
